export const getShowSecretWithoutModeUrl = (
  projectID: number,
  name: string,
) => {
  return `/secrets/secret/${projectID}/${name}`;
};

/**
 * pylon's api_tools.with_modes registers the mode-less URL alongside the mode-ful one for every resource, and proxy_method defaults `mode` to "default", so this is the project handler under another URL. It is spelled out here because elitea-sdk is a live caller: elitea_sdk/runtime/clients/client.py:108 and sandbox_client.py:237 build {api_v2}/secrets/secret/{project_id} and append /{name}. pylon serves the mode-less form of the other five routes too; elitea-main does not, because nothing in the workspace calls them.
 * @summary Read one secret — the mode-less legacy form
 */
export const showSecretWithoutMode = async (
  projectID: number,
  name: string,
  options?: Parameters<typeof eliteaFetch>[1],
): Promise<showSecretWithoutModeResponse> => {
  return eliteaFetch<showSecretWithoutModeResponse>(
    getShowSecretWithoutModeUrl(projectID, name),
    {
      ...options,
      method: "GET",
    },
  );
};

export const getShowSecretWithoutModeQueryKey = (
  projectID: number,
  name: string,
) => {
  return [`/secrets/secret/${projectID}/${name}`] as const;
};

export const getShowSecretWithoutModeQueryOptions = <
  TData = Awaited<ReturnType<typeof showSecretWithoutMode>>,
  TError = N401Response | N403Response | N404Response,
>(
  projectID: number,
  name: string,
  options?: {
    query?: Partial<
      UseQueryOptions<
        Awaited<ReturnType<typeof showSecretWithoutMode>>,
        TError,
        TData
      >
    >;
    request?: SecondParameter<typeof eliteaFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getShowSecretWithoutModeQueryKey(projectID, name);

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof showSecretWithoutMode>>
  > = ({ signal }) =>
    showSecretWithoutMode(projectID, name, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled:
      projectID !== null &&
      projectID !== undefined &&
      name !== null &&
      name !== undefined,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof showSecretWithoutMode>>,
    TError,
    TData
  > & { queryKey: DataTag<QueryKey, TData, TError> };
};

